-- -- ============================================================
-- -- 37. FAQS
-- -- ============================================================
-- insert into public.faqs (id, question, answer, category, sort_order, is_featured_on_home, internal_link_label, internal_link_url, is_active, business_id) values
--   ('00000000-0000-0000-0000-0000000000f1', 'How do I book an appointment?', 'You can book directly via our online booking engine on this website in under 60 seconds. Simply select your desired grooming or spa service, choose your preferred master barber, pick a date and time slot, and enter your details for instant confirmation.', 'Appointments', 1, true, 'Book an Appointment', '/services', true, '00000000-0000-0000-0000-000000000001'),
--   ('00000000-0000-0000-0000-0000000000f2', 'Can I choose my preferred barber?', 'Yes, absolutely. You can select any of our certified master barbers based on their specialty (such as Samuel Mwangi for precision fades or Eric Omondi for hot towel beard sculpting). You may also choose Any Available Master for earlier openings.', 'Appointments', 2, true, 'View Master Barbers', '/barbers', true, '00000000-0000-0000-0000-000000000001'),
--   ('00000000-0000-0000-0000-0000000000f3', 'How much deposit is required?', 'We do not charge an upfront deposit for standard single appointments booked online. For private VIP CEO packages or groups (e.g. groomsmen parties of 3+), our concierge will reach out via WhatsApp to confirm your slot.', 'Payments', 3, true, 'Explore Services', '/services', true, '00000000-0000-0000-0000-000000000001'),
--   ('00000000-0000-0000-0000-0000000000f4', 'Can I reschedule my appointment?', 'Yes. You can reschedule or cancel at no charge up to 2 hours before your scheduled appointment time by clicking the link in your booking confirmation email or messaging our concierge on WhatsApp.', 'Appointments', 4, false, NULL, NULL, true, '00000000-0000-0000-0000-000000000001'),
--   ('00000000-0000-0000-0000-0000000000f5', 'How early should I arrive?', 'We recommend arriving 5 to 10 minutes prior to your scheduled time. Enjoy a complimentary single-origin Kenyan pour-over coffee, cold brew, or sparkling mineral water in our executive lounge.', 'Appointments', 5, false, NULL, NULL, true, '00000000-0000-0000-0000-000000000001'),
--   ('00000000-0000-0000-0000-0000000000f6', 'What payment methods are accepted?', 'We accept Safaricom M-Pesa (Till & Paybill), Visa, Mastercard, American Express, Apple Pay, and Cash at checkout in our Kilimani studio.', 'Payments', 6, false, NULL, NULL, true, '00000000-0000-0000-0000-000000000001'),
--   ('00000000-0000-0000-0000-0000000000f7', 'When do I pay the remaining balance?', 'Full payment is settled comfortably at our reception counter immediately following your finished grooming and styling session.', 'Payments', 7, false, NULL, NULL, true, '00000000-0000-0000-0000-000000000001'),
--   ('00000000-0000-0000-0000-0000000000f8', 'How long does a haircut take?', 'Our signature haircuts typically take 45 to 60 minutes. This includes a pre-cut scalp and lifestyle consultation, precision shear or clipper sculpting, razor neck cleanup, hair wash, and professional blow-dry styling.', 'Services', 8, false, 'View All Haircuts', '/services', true, '00000000-0000-0000-0000-000000000001'),
--   ('00000000-0000-0000-0000-0000000000f9', 'What services are available?', 'We offer master haircuts, hot lather straight razor shaves, botanical beard sculpting, restorative scalp treatments, manicures, pedicures, and signature executive packages such as The CEO Experience.', 'Services', 9, false, 'Explore Service Menu', '/services', true, '00000000-0000-0000-0000-000000000001'),
--   ('00000000-0000-0000-0000-00000000001a', 'Can I book multiple services?', 'Yes, you can combine multiple grooming and wellness treatments into a single visit. When booking, select all desired treatments and our system will allocate consecutive time slots with your designated master.', 'Services', 10, false, NULL, NULL, true, '00000000-0000-0000-0000-000000000001'),
--   ('00000000-0000-0000-0000-00000000001b', 'Can I choose a specific barber?', 'Every master barber at The Icons has a dedicated profile detailing their years of craftsmanship, signature specialties, and customer ratings. You can pick your specific barber whenever you reserve.', 'Barbers', 11, false, 'Meet Our Team', '/barbers', true, '00000000-0000-0000-0000-000000000001'),
--   ('00000000-0000-0000-0000-00000000001c', 'What happens if my preferred barber is unavailable?', 'If your chosen artisan is fully booked on your preferred date, you can opt for another senior master of equivalent craft level, or contact our concierge via WhatsApp to be placed on our VIP priority standby list.', 'Barbers', 12, false, NULL, NULL, true, '00000000-0000-0000-0000-000000000001'),
--   ('00000000-0000-0000-0000-00000000001d', 'Can I purchase grooming products?', 'Yes, our curated line of botanical scalp clarifiers, argan beard oils, matte clays, and executive travel sets are available for direct purchase both online with doorstep delivery and at our Kilimani salon boutique.', 'Products', 13, false, 'Browse Grooming Products', '/products', true, '00000000-0000-0000-0000-000000000001'),
--   ('00000000-0000-0000-0000-00000000001e', 'Are products available at the shop?', 'All products showcased in our digital apothecary are stocked at our Penthouse Suite. Your barber can demonstrate application techniques and recommend formulas tailored to your hair and skin profile.', 'Products', 14, false, NULL, NULL, true, '00000000-0000-0000-0000-000000000001'),
--   ('00000000-0000-0000-0000-00000000001f', 'What happens if I cancel or miss my appointment?', 'We kindly request at least 2 hours advance notice for cancellations or rescheduling. For no-shows on private suites or group packages, a re-booking fee may apply to respect our artisans'' reserved time.', 'Policies', 15, false, NULL, NULL, true, '00000000-0000-0000-0000-000000000001'),
--   ('00000000-0000-0000-0000-000000000020', 'What hygiene and sterilization standards do you maintain?', 'We enforce clinical hospital-grade hygiene protocols. Metal clippers, guards, and shears undergo ultrasonic cleaning and autoclave sterilization between clients. Straight razor blades are strictly 100% single-use and disposed of in medical sharps containers.', 'Policies', 16, false, NULL, NULL, true, '00000000-0000-0000-0000-000000000001')
-- on conflict (id) do nothing;

